protected void loadModule()
{
    NumberSeqDatatype datatype = NumberSeqDatatype::construct();

    datatype.parmDatatypeId(extendedtypenum(NVTrvWorkerExpenseRequestId));
    datatype.parmReferenceLabel((literalstr("Travel expense request Id")));
    datatype.parmReferenceHelp(literalstr("Unique key for travel expense request Id"));
    datatype.parmWizardIsContinuous(true);
    datatype.parmWizardIsManual(NoYes::No);
    datatype.parmWizardIsChangeDownAllowed(NoYes::No);
    datatype.parmWizardIsChangeUpAllowed(NoYes::No);
    datatype.parmSortField(18);

    this.create(datatype);

    /*datatype.parmDatatypeId(extendedtypenum(HcmJobId));
