    datatype.parmWizardIsChangeUpAllowed(NoYes::No);
    datatype.parmSortField(19);

    this.create(datatype);*/
}

[SubscribesTo(classstr(NumberSeqModuleHRM), delegatestr(NumberSeqModuleHRM, loadedModule))]
public static void loadModuleEventHandler(NumberSeqModuleHRM _numberSeqModuleHRM, NumberSeqDatatype _datatype)
{
    _datatype.parmDatatypeId(extendedtypenum(HcmJobId));
    _datatype.parmReferenceLabel("@PersonnelCore:Job");
    _datatype.parmReferenceHelp("@PersonnelCore:Job");
    _datatype.parmWizardIsContinuous(true);
    _datatype.parmWizardIsManual(NoYes::No);
    _datatype.parmWizardIsChangeDownAllowed(NoYes::No);
    _datatype.parmWizardIsChangeUpAllowed(NoYes::No);
    _datatype.parmSortField(25);

    _numberSeqModuleHRM.createNumberSequence(_datatype);
}

[SubscribesTo(classstr(NumberSeqGlobal), delegateStr(NumberSeqGlobal, buildModulesMapDelegate))]
static void buildModulesMapSubscribes(Map numberSeqModuleNameMap)
{
    NumberSeqGlobal::addModuleToMap(classNum(NVNumberSeqApplicationModuleHRM), numberSeqModuleNameMap);
}

public static NVTrvWorkerExpenseRequestId getTrvWorkerExpenseRequestId()
{
    NumberSequenceReference numSeqRef = NumberSeqReference::findReference(extendedTypeNum(NVTrvWorkerExpenseRequestId));
    NumberSeq num = NumberSeq::newGetNum(numSeqRef);

    num.used();

    return num.num();
}

public static NumberSequenceReference getHcmJobNumSeqRef()
{
    NumberSequenceReference numSeqRef = NumberSeqReference::findReference(extendedTypeNum(NVHcmJobNumSequence));

    return numSeqRef;
}
